{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.slikk_master as WITH inward_data AS ( SELECT SKU_GROUP, MIN(DATE) AS first_inward_date, SUM(OPENING_INVENTORY) AS opening_inventory FROM snitch_db.maplemonk.slikk_inventory GROUP BY SKU_GROUP ), sales_after_inward AS ( SELECT k.SKU_GROUP, i.first_inward_date, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 7, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_7, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 15, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_15, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 30, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_30 FROM snitch_db.maplemonk.slikk_fact_item k JOIN inward_data i ON k.SKU_GROUP = i.SKU_GROUP GROUP BY k.SKU_GROUP, i.first_inward_date ), str_data AS ( SELECT s.SKU_GROUP, i.opening_inventory, DIV0(s.sales_day_7, i.opening_inventory) AS STR_DAY_7, DIV0(s.sales_day_15, i.opening_inventory) AS STR_DAY_15, DIV0(s.sales_day_30, i.opening_inventory) AS STR_DAY_30 FROM sales_after_inward s JOIN inward_data i ON s.SKU_GROUP = i.SKU_GROUP ), sku_group_data AS ( SELECT sku_group, order_date, SUM(TOTAL_QUANTITY) AS suborder_quantity, SUM(return_quantity) AS return_quantity, MAX(MRP) AS mrp, SUM(SP) as SP FROM ( SELECT sku_group, order_date, TOTAL_QUANTITY, return_quantity, MRP, SP FROM snitch_db.MAPLEMONK.slikk_fact_item ) GROUP BY 1, 2 ), first_order_dates AS ( SELECT sku_group, MIN(order_date) AS first_order_date, DATEDIFF(\'DAY\', MIN(order_date), CURRENT_DATE) AS days_since_first_order, DATEDIFF(\'DAY\', MIN(order_date), MAX(order_date)) AS total_days_sold FROM sku_group_data GROUP BY sku_group ), total_sales AS ( SELECT sku_group_data.sku_group, first_order_dates.first_order_date, first_order_dates.days_since_first_order, first_order_dates.total_days_sold, MAX(MRP) AS MRP, DIV0(SUM(SP), SUM(suborder_quantity)) as ASP, SUM(return_quantity) AS total_returns, SUM(suborder_quantity) AS total_sales, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 30, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_30_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 15, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_15_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 7, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_7_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 90, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_90_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 60, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_60_days, SUM(CASE WHEN order_date <= DATEADD(\'DAY\', 180, first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_180_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 30 THEN suborder_quantity ELSE 0 END) AS sales_last_30_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 15 THEN suborder_quantity ELSE 0 END) AS sales_last_15_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 7 THEN suborder_quantity ELSE 0 END) AS sales_last_7_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 60 THEN suborder_quantity ELSE 0 END) AS sales_last_60_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 90 THEN suborder_quantity ELSE 0 END) AS sales_last_90_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 180 THEN suborder_quantity ELSE 0 END) AS sales_last_180_days, CASE WHEN first_order_dates.total_days_sold = 0 THEN SUM(suborder_quantity) ELSE SUM(suborder_quantity) / first_order_dates.total_days_sold END AS natural_ros FROM sku_group_data INNER JOIN first_order_dates ON sku_group_data.sku_group = first_order_dates.sku_group GROUP BY sku_group_data.sku_group, first_order_dates.first_order_date, first_order_dates.days_since_first_order, first_order_dates.total_days_sold ), enhanced_total_sales AS ( SELECT total_sales.*, GREATEST( total_sales.sales_first_30_days / 30, total_sales.sales_last_30_days / 30, total_sales.natural_ros ) AS max_first_30_last_30_natural_ros, GREATEST( total_sales.sales_first_30_days / 30, total_sales.sales_last_30_days / 30, total_sales.natural_ros, total_sales.sales_first_7_days / 7 ) AS max_first_30_last_30_natural_ros_first_7_days, CASE WHEN total_sales = 0 THEN 0 ELSE (total_returns/total_sales)*100 END AS average_return_since_first_order, CASE WHEN max_first_30_last_30_natural_ros > 5 THEN max_first_30_last_30_natural_ros WHEN max_first_30_last_30_natural_ros < 5 AND max_first_30_last_30_natural_ros_first_7_days > 10 THEN max_first_30_last_30_natural_ros_first_7_days WHEN total_sales > 800 THEN GREATEST(natural_ros, sales_last_7_days / 7) ELSE natural_ros END AS final_ros FROM total_sales ), PivotTable AS ( SELECT TRIM(UPPER(sku_group)) AS sku_group, SUM(Sellable_Inventory) AS Sellable_Inventory, SUM(XS_units) AS XS_units, SUM(S_units) AS S_units, SUM(M_units) AS M_units, SUM(L_units) AS L_units, SUM(XL_units) AS XL_units, SUM(XXL_units) AS XXL_units, SUM(XL3_units) AS XL3_units, SUM(XL4_units) AS XL4_units, SUM(XL5_units) AS XL5_units, SUM(XL6_units) AS XL6_units, SUM(XL7_units) AS XL7_units, SUM(XL8_units) AS XL8_units, SUM(NA_units) AS NA_units, MAX(num_size_available) AS num_size_available FROM ( SELECT sku_group, SUM(OPENING_INVENTORY) AS Sellable_Inventory, COALESCE(SUM(CASE WHEN SIZE = \'XS\' OR SIZE = \'28\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN SIZE = \'S\' OR SIZE = \'30\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN SIZE = \'M\' OR SIZE = \'32\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN SIZE = \'L\' OR SIZE = \'34\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XL_units, COALESCE(SUM(CASE WHEN SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN OPENING_INVENTORY ELSE 0 END), 0) AS XXL_units, COALESCE(SUM(CASE WHEN SIZE = \'3XL\' OR SIZE = \'40\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XL3_units, COALESCE(SUM(CASE WHEN SIZE = \'4XL\' OR SIZE = \'42\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XL4_units, COALESCE(SUM(CASE WHEN SIZE = \'5XL\' OR SIZE = \'44\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XL5_units, COALESCE(SUM(CASE WHEN SIZE = \'6XL\' OR SIZE = \'46\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XL6_units, COALESCE(SUM(CASE WHEN SIZE = \'7XL\' OR SIZE = \'48\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XL7_units, COALESCE(SUM(CASE WHEN SIZE = \'8XL\' OR SIZE = \'50\' THEN OPENING_INVENTORY ELSE 0 END), 0) AS XL8_units, COALESCE(SUM(CASE WHEN LEFT(REVERSE(SUBSTRING(REVERSE(Sku_group), CHARINDEX(\'-\', REVERSE(Sku_group)) + 1, LEN(Sku_group))), 4) IN (\'4MSF\',\'4MAC\',\'SH01\',\'4MBL\',\'SH00\',\'BP00\',\'SN00\') THEN OPENING_INVENTORY ELSE 0 END), 0) AS NA_units, (CASE WHEN SIZE = \'XS\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'S\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'M\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'L\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'XL\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'XXL\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'3XL\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'4XL\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'5XL\' THEN 1 ELSE 0 END) + (CASE WHEN SIZE = \'6XL\' THEN 1 ELSE 0 END) AS num_size_available FROM snitch_db.maplemonk.slikk_inventory WHERE date = current_date GROUP BY sku_group, SIZE ) WHERE LOWER(sku_group) NOT LIKE \'cb%\' GROUP BY sku_group ), availability_master_v2 AS ( SELECT * FROM snitch_db.maplemonk.availability_master_v2 ), metafields_data AS ( SELECT DISTINCT TRIM(UPPER(SKU_GROUP)) AS sku_group, TITLE, PRINT_DESIGN, COLLAR_NEW, MATERIAL_NEW, FIT, COLOR, SLEEVE_TYPE FROM snitch_db.maplemonk.metafields_data ) SELECT COALESCE(a.sku_group, b.sku_group) AS sku_group, a.first_order_date, a.days_since_first_order, a.total_days_sold, a.MRP, a.ASP, a.total_returns, a.total_sales, a.sales_first_30_days, a.sales_first_15_days, a.sales_first_7_days, a.sales_first_90_days, a.sales_first_60_days, a.sales_first_180_days, a.sales_last_30_days, a.sales_last_15_days, a.sales_last_7_days, a.sales_last_60_days, a.sales_last_90_days, a.sales_last_180_days, a.natural_ros, a.max_first_30_last_30_natural_ros, a.max_first_30_last_30_natural_ros_first_7_days, a.average_return_since_first_order, a.final_ros, d.opening_inventory, d.STR_DAY_7, d.STR_DAY_15, d.STR_DAY_30, b.SELLABLE_INVENTORY, b.XS_UNITS, b.S_UNITS, b.M_UNITS, b.L_UNITS, b.XL_UNITS, b.XXL_UNITS, b.XL3_UNITS, b.XL4_UNITS, b.XL5_UNITS, b.XL6_UNITS, b.XL7_UNITS, b.XL8_UNITS, b.NA_UNITS, b.num_size_available, CASE WHEN (CASE WHEN b.M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN b.L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN b.XL_units > 0 THEN 1 ELSE 0 END) < 3 THEN \'Cut Size\' ELSE \'Full Size\' END AS Cute_Size_Fag, DIV0((a.TOTAL_SALES - a.TOTAL_RETURNS), (a.TOTAL_SALES - a.TOTAL_RETURNS + B.SELLABLE_INVENTORY)) * 100 AS Sell_through, DIV0(B.SELLABLE_INVENTORY, (DIV0(a.SALES_LAST_30_DAYS, 30))) AS DOI, c.PRODUCT_NAME, c.CATEGORY, c.SKU_CLASS, c.SELLABLE_INVENTORY AS warehouse_inventory, c.XS_UNITS AS warehouse_XS_UNITS, c.S_UNITS AS warehouse_S_UNITS, c.M_UNITS AS warehouse_M_UNITS, c.L_UNITS AS warehouse_L_UNITS, c.XL_UNITS AS warehouse_XL_UNITS, c.XXL_UNITS AS warehouse_XXL_UNITS, c.XL3_UNITS AS warehouse_XL3_UNITS, c.XL4_UNITS AS warehouse_XL4_UNITS, c.XL5_UNITS AS warehouse_XL5_UNITS, c.XL6_UNITS AS warehouse_XL6_UNITS, c.XL7_UNITS AS warehouse_XL7_UNITS, c.XL8_UNITS AS warehouse_XL8_UNITS, c.NA_UNITS AS warehouse_NA_UNITS, c.NUM_SIZE_AVAILABLE AS warehouse_NUM_SIZE_AVAILABLE, m.TITLE, m.PRINT_DESIGN, m.COLLAR_NEW, m.MATERIAL_NEW, m.FIT, m.COLOR, m.SLEEVE_TYPE FROM enhanced_total_sales a FULL OUTER JOIN PivotTable b ON a.sku_group = b.sku_group LEFT JOIN str_data d ON COALESCE(a.sku_group, b.sku_group) = d.sku_group LEFT JOIN availability_master_v2 c ON COALESCE(a.sku_group, b.sku_group) = c.sku_group LEFT JOIN metafields_data m ON COALESCE(a.sku_group, b.sku_group) = m.sku_group ORDER BY a.total_sales DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            